import{_ as t,o as a,c as r,ah as o}from"./chunks/framework.CRsDMGp2.js";const p=JSON.parse('{"title":"Guide — Project manager & Collaborators","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/chef-projet-collaborateurs.md","filePath":"src/en/guide/chef-projet-collaborateurs.md"}'),n={name:"en/guide/chef-projet-collaborateurs.md"};function s(i,e,l,c,d,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="guide-—-project-manager-collaborators" tabindex="-1">Guide — Project manager &amp; Collaborators <a class="header-anchor" href="#guide-—-project-manager-collaborators" aria-label="Permalink to &quot;Guide — Project manager &amp; Collaborators&quot;">​</a></h1><p>Run and execute projects day to day.</p><p>This guide covers two closely related profiles: the <strong>Project manager</strong>, who runs a project end to end, and <strong>Collaborators / Consultants</strong> (7 job types), who carry out the technical work assigned to them.</p><h2 id="part-a-—-project-manager" tabindex="-1">Part A — Project manager <a class="header-anchor" href="#part-a-—-project-manager" aria-label="Permalink to &quot;Part A — Project manager&quot;">​</a></h2><h3 id="creating-and-running-a-project" tabindex="-1">Creating and running a project <a class="header-anchor" href="#creating-and-running-a-project" aria-label="Permalink to &quot;Creating and running a project&quot;">​</a></h3><ul><li>Create a new project from <strong>Projects &gt; New project</strong>: client, project manager, an optional referrer, and a <strong>project type</strong>. The chosen type automatically pre-fills the default phases and milestones of the matching methodology (eight types available: Website / digital presence, Custom application or platform, Digital transformation consulting, Information systems architecture, Cloud &amp; infrastructure, Cybersecurity, AI &amp; data, Training).</li><li>Adjust the pre-filled phases and milestones if needed (rename, reorder, set each billable milestone&#39;s billing percentage) from the project page&#39;s <strong>Tracking</strong> tab.</li><li>Build the project team from the <strong>Team</strong> tab and assign tasks, including to external partners — specify their compensation type (flat fee, milestone percentage, or daily rate).</li><li>Track overall progress via the <strong>Gantt</strong> view (by phase and milestone) or the <strong>Kanban</strong> view (by task status).</li></ul><h3 id="milestones-and-billing" tabindex="-1">Milestones and billing <a class="header-anchor" href="#milestones-and-billing" aria-label="Permalink to &quot;Milestones and billing&quot;">​</a></h3><ul><li>When a <strong>non-billable</strong> milestone is reached, add a report visible to the client (and, when relevant, a preview link to a working version of the project at that stage).</li><li>When a <strong>billable</strong> milestone is reached, the amount due is recorded, based on its billing percentage. Flag it to the administrator, who takes care of issuing the corresponding invoice.</li><li>If an invoice remains unpaid past the agreed period, you can suspend or lift the project&#39;s access suspension, alongside the administrator.</li></ul><h3 id="amendments-and-closing" tabindex="-1">Amendments and closing <a class="header-anchor" href="#amendments-and-closing" aria-label="Permalink to &quot;Amendments and closing&quot;">​</a></h3><ul><li>Initiate an amendment request from the <strong>Amendments</strong> tab if the project&#39;s scope, timeline or budget needs to change. The administrator then formalizes the document, which goes out for the client&#39;s electronic signature; the budget impact only applies once the amendment is signed.</li><li>When closing the project, tick the optional <strong>NextBoxx</strong> eligibility and add a free-text note if the project can serve as a real-world case study for internal training.</li></ul><h2 id="part-b-—-collaborators-consultants" tabindex="-1">Part B — Collaborators / Consultants <a class="header-anchor" href="#part-b-—-collaborators-consultants" aria-label="Permalink to &quot;Part B — Collaborators / Consultants&quot;">​</a></h2><p>The core journey is the same regardless of your job type (Digital transformation consultant, Developer, Systems architect, Cloud &amp; infrastructure expert, Cybersecurity expert, AI &amp; data expert, Internal trainer) — only the expected deliverable changes.</p><h3 id="your-assignments" tabindex="-1">Your assignments <a class="header-anchor" href="#your-assignments" aria-label="Permalink to &quot;Your assignments&quot;">​</a></h3><ul><li>View the tasks assigned to you, across every project, from your dashboard or a project&#39;s <strong>Tasks</strong> tab.</li><li>Update their progress (to do, in progress, done) and upload your deliverables directly from their page.</li><li>Talk with the project manager and, depending on context, the client, via the project&#39;s built-in messaging.</li></ul>',14)])])}const u=t(n,[["render",s]]);export{p as __pageData,u as default};
